Ui.Script:
-- Fix for MoneyFrame nil error: hook before any SmallMoneyFrameTemplate frames are created
local original_MoneyFrame_Update = MoneyFrame_Update;
MoneyFrame_Update = function(frameName, money, forceShow)
	if money == nil then
		money = 0;
	end
	return original_MoneyFrame_Update(frameName, money, forceShow);
end
